import{_ as t,o as a,c as i,a3 as s}from"./chunks/framework.DEy3KOfk.js";const u=JSON.parse('{"title":"Creating an action","description":"","frontmatter":{"navigation":{"category":"Getting started"},"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/docs/creating-an-action.md"},"headers":[],"relativePath":"guides/creating-an-action.md","filePath":"docs/creating-an-action.md","lastUpdated":1791360073000}'),n={name:"guides/creating-an-action.md"};function o(d,e,c,r,l,p){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="creating-an-action" tabindex="-1">Creating an action <a class="header-anchor" href="#creating-an-action" aria-label="Permalink to &quot;Creating an action&quot;">​</a></h1><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen:action</span></span></code></pre></div><p>This runs the <code>action</code> Turborepo generator in <code>turbo/generators/</code>. It asks for the action&#39;s folder name, display name and one-line description. To pass those answers directly:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gen:action</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --args</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-action</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;My Action&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Does something useful&quot;</span></span></code></pre></div><p>The folder name uses kebab-case and must not exist under <code>actions/</code> already. The generator prompts for all three values; the display name defaults to a title-cased folder name.</p><h2 id="what-it-creates" tabindex="-1">What it creates <a class="header-anchor" href="#what-it-creates" aria-label="Permalink to &quot;What it creates&quot;">​</a></h2><ol><li><code>actions/&lt;folder&gt;/action.yml</code>, a Node 24 JavaScript action that runs <code>src/index.mjs</code> without a compilation or bundling step.</li><li><code>src/index.mjs</code> with a runnable placeholder and <code>src/index.test.mjs</code> with a co-located smoke test. Shared <code>getInput()</code> and <code>setOutput()</code> helpers, with regression tests for GitHub&#39;s input names and output-file format, live once in <code>actions/common/src/</code>.</li><li>A <code>README.md</code>, <code>CHANGELOG.md</code> and <code>version.txt</code>, initialized to <code>0.0.0</code>. The README&#39;s Inputs and Outputs tables are generated from <code>action.yml</code>; actions with no declared values get an explicit “no inputs/outputs” note.</li><li>Entries in <code>release-please-config.json</code> and <code>.release-please-manifest.json</code>. The action&#39;s first release is pinned to <code>0.0.1</code>, and later releases get independent <code>&lt;folder&gt;-v&lt;version&gt;</code> tags.</li><li>A row in the Actions table in the root <code>README.md</code>.</li></ol><p>The generator formats the files after creating them. It does not commit anything.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li>Add inputs and outputs to <code>action.yml</code>. Import <code>getInput</code> and <code>setOutput</code> from <code>../../common/src/utils.mjs</code> in <code>src/index.mjs</code>; GitHub preserves hyphens in names such as <code>INPUT_PLUGIN-NAME</code>. See the warning in <a href="./ci-and-releases#registering-an-action-for-releases">CI and releases</a>.</li><li>Document input and output descriptions in <code>action.yml</code>. Do not edit the generated README tables directly; <code>pnpm readme</code> regenerates them and <code>pnpm readme:check</code> checks them for drift.</li><li>Implement the action in <code>src/index.mjs</code> and cover its behavior in <code>src/*.test.mjs</code>. Action tests live beside their implementation and CI runs tests only for the changed action.</li><li>Update the README&#39;s hand-written overview and usage examples, then run <code>pnpm readme</code> to generate its input/output tables and refresh the root action table.</li></ul><p>Each action has an independent GitHub release and can be referenced by its subdirectory path. GitHub does not automatically list action metadata files nested in a monorepo in the Marketplace; see <a href="./ci-and-releases#registering-an-action-for-releases">CI and releases</a> for the release setup.</p>',11)])])}const m=t(n,[["render",o]]);export{u as __pageData,m as default};
